import io
import os
import sys

repositoryRoot = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                               '..', '..'))
if os.path.join(repositoryRoot, 'definitions') not in sys.path:
    sys.path.insert(0, os.path.join(repositoryRoot, 'definitions'))

from outputVariableTypes import outputVariableTypes, reservedBits

headerPath = os.path.join(repositoryRoot, 'src', 'Autogenerated', 'OutputVariableTypes.h')

#the mask is Index64, so 64 bits and not one more; _None is the empty mask and carries no bit
maximumBit = 63


#%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
def CheckBitAllocation():
    """Every bit is allocated exactly once and fits the 64 bit mask. Reserved bits count as
    allocated, so a number that was once handed out is never handed out again."""
    used = {}
    for variable in list(outputVariableTypes) + list(reservedBits):
        if variable.bit is None:
            if variable.name != '_None':
                raise ValueError(variable.name + ': only _None may have no bit')
            continue
        if not (0 <= variable.bit <= maximumBit):
            raise ValueError(variable.name + ': bit ' + str(variable.bit)
                             + ' is outside the 64 bit mask')
        if variable.bit in used:
            raise ValueError('bit ' + str(variable.bit) + ' is claimed by both '
                             + used[variable.bit] + ' and ' + variable.name)
        used[variable.bit] = variable.name

    return used


#%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
def Aligned(text, width):
    return text + ' ' * max(1, width - len(text))


#%%++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
def EmitHeader():
    """Write the enum and the two functions that used to be maintained beside it by hand."""
    CheckBitAllocation()

    variables = [v for v in outputVariableTypes if v.name != '_None']
    nameWidth = max([len(v.name) for v in variables]) + 1

    s = ''
    s += '/** ' + '*' * 92 + '\n'
    s += '* @brief        AUTO GENERATED FILE - DO NOT EDIT\n'
    s += '*\n'
    s += '* @details      OutputVariableType, generated from definitions/outputVariableTypes.py\n'
    s += '*               by tools/generators/outputVariableEmitter.py. Add an output variable\n'
    s += '*               there, with the next free bit; never reuse a bit that was handed out.\n'
    s += '*\n'
    s += '* @author       Gerstmayr Johannes\n'
    s += '* @copyright    This file is part of Exudyn. Exudyn is free software: see LICENSE.txt\n'
    s += '*\n'
    s += '************************************************************************************* */\n'
    s += '\n'
    s += '#ifndef OUTPUTVARIABLETYPES__H\n'
    s += '#define OUTPUTVARIABLETYPES__H\n'
    s += '\n'
    s += '//! OutputVariable used for output data in objects, nodes, loads, ...\n'
    s += '//! the type is a 64 bit mask: types can be combined, e.g. for the variables an item\n'
    s += '//! provides. All cases are independent of 2D/3D, which the item itself knows.\n'
    s += 'enum class OutputVariableType : Index64 {\n'
    s += '    ' + Aligned('_None', nameWidth) + '= 0ull, //!< marks that no type is used\n'
    for variable in variables:
        s += ('    ' + Aligned(variable.name, nameWidth) + '= 1ull << ' + str(variable.bit)
              + ', //!< ' + variable.description + '\n')
    if reservedBits:
        s += '\n'
        s += '    //bits below are ALLOCATED and must not be reused:\n'
        for variable in reservedBits:
            s += ('    //' + Aligned(variable.name, nameWidth - 2) + '= 1ull << '
                  + str(variable.bit) + ', //!< ' + variable.description + '\n')
    s += '};\n'
    s += '\n'
    s += '//! return whether given OutputVariableType can be evaluated for reference configuration\n'
    s += 'inline bool IsOutputVariableTypeForReferenceConfiguration(OutputVariableType var)\n'
    s += '{\n'
    s += '    const Index64 refTypes =\n'
    referenceVariables = [v for v in variables if v.referenceConfiguration]
    for index, variable in enumerate(referenceVariables):
        separator = ';' if index + 1 == len(referenceVariables) else ' +'
        s += '        (Index64)OutputVariableType::' + variable.name + separator + '\n'
    s += '\n'
    s += '    if (EXUstd::IsOfTypeAndNotNone(refTypes, (Index64)var)) { return true; }\n'
    s += '    return false;\n'
    s += '}\n'
    s += '\n'
    s += '//! OutputVariable string conversion\n'
    s += 'inline const char* GetOutputVariableTypeString(OutputVariableType var)\n'
    s += '{\n'
    s += '    switch (var)\n'
    s += '    {\n'
    s += '    case OutputVariableType::_None: return "_None";\n'
    for variable in variables:
        s += ('    case OutputVariableType::' + variable.name + ': return "'
              + variable.name + '";\n')
    s += '    default: SysError("GetOutputVariableTypeString: invalid variable type");\n'
    s += '        return "Invalid";\n'
    s += '    }\n'
    s += '}\n'
    s += '\n'
    s += '#endif //OUTPUTVARIABLETYPES__H\n'

    existing = ''
    if os.path.exists(headerPath):
        existing = io.open(headerPath, encoding='utf8').read()
    if existing != s:
        io.open(headerPath, 'w', encoding='utf8', newline='\n').write(s)

    return existing != s
